export function pair(a: any, b: any): [any, any] {
  return [a, b];
}

import { pair } from '../src/pair.ts';
const p = pair('BE-201', 40);
const code: string = p[0];   // must be a string
const seats: number = p[1];  // must be a number
export { code, seats };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pair } from '../src/pair.ts';

test('pair', () => assert.deepEqual(pair('BE-201', 40), ['BE-201', 40]));

